scripts.clue-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'clue-store',
  description:
    "The word-clue game's engine (game.json). action:'board' reads the game; 'give_clue' records a clue; 'guess' reveals a word the player picked; 'pass' ends the player's guessing; 'new_game' deals a fresh board.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'board', 'give_clue', 'guess', 'pass', 'new_game'.",
      required: true,
    },
    clue: { type: 'string', description: 'For give_clue: one word, not on the board.' },
    count: { type: 'number', description: 'For give_clue: how many of the player’s words it points at.' },
    say: { type: 'string', description: 'For give_clue: one short line of table talk.' },
    word: { type: 'string', description: 'For guess: the board word the player picked.' },
  },
  outputs: {
    status: {
      type: 'string',
      description: "'clue_needed', 'guessing', 'won', 'lost' or 'new'.",
    },
    giver: { type: 'string', description: "Whose clue is next: 'a' (Woordsmid) or 'b' (Puzzelaar)." },
    result: { type: 'string', description: "For guess: 'target', 'neutral', 'trap', or ''." },
    display: { type: 'string', description: 'For give_clue: the clue as shown to the player.' },
    modelState: { type: 'json', description: 'What the clue-giver sees: its words, the trap, the rest.' },
    summary: { type: 'string', description: 'A short summary of the game.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── clue-rules-start ──
// The board is sixteen words: six are the player's, nine are neutral, one
// is the trap. A clue-giver who knows the board gives one word and a count;
// the player then picks up to count + 1 words. A neutral word ends their
// turn, the trap ends the game, and finding all six wins it. Kept
// self-contained between these sentinels so unit tests execute the shipped
// bytes.
var BOARD_SIZE = 16;
var TARGETS = 6;

function shuffle(list, random) {
  var out = list.slice();
  for (var i = out.length - 1; i > 0; i -= 1) {
    var j = Math.floor(random() * (i + 1));
    var t = out[i];
    out[i] = out[j];
    out[j] = t;
  }
  return out;
}

function deal(bank, random) {
  var picked = shuffle(bank, random).slice(0, BOARD_SIZE);
  var cells = picked.map(function (word, i) {
    return { word: word, kind: i < TARGETS ? 'target' : i === TARGETS ? 'trap' : 'neutral', revealed: false };
  });
  return shuffle(cells, random);
}

function remaining(words, kind) {
  return words.filter(function (w) { return w.kind === kind && !w.revealed; }).map(function (w) { return w.word; });
}

// Why a clue is not allowed on this board, or '' when it is.
function clueProblem(words, clue, count) {
  var c = String(clue || '').trim().toLowerCase();
  if (!/^[a-zÀ-ɏ'-]{2,24}$/.test(c)) return 'A clue is one word of letters, like "ocean".';
  for (var i = 0; i < words.length; i += 1) {
    var w = words[i].word.toLowerCase();
    if (w === c) return '"' + c + '" is on the board.';
    // Forms of a board word (plurals, compounds that start with it) give the
    // answer away; a word that merely contains one ("planet", "net") does not.
    var shorter = c.length < w.length ? c : w;
    var longer = c.length < w.length ? w : c;
    if (shorter.length >= 3 && longer.indexOf(shorter) === 0)
      return '"' + c + '" is a form of the board word "' + w + '".';
  }
  var left = remaining(words, 'target').length;
  if (!(count >= 1 && count <= left && Math.floor(count) === count))
    return 'The count must be a whole number from 1 to ' + left + '.';
  return '';
}

function applyGuess(game, word) {
  var pick = String(word || '').trim().toLowerCase();
  var cell = game.words.find(function (w) { return w.word.toLowerCase() === pick; });
  if (!cell) return { error: '"' + word + '" is not on the board.' };
  if (cell.revealed) return { error: '"' + cell.word + '" is already revealed.' };
  cell.revealed = true;
  var result = cell.kind;
  if (result === 'trap') {
    game.status = 'lost';
  } else if (remaining(game.words, 'target').length === 0) {
    game.status = 'won';
  } else if (result === 'neutral') {
    endGuessing(game);
  } else {
    game.clue.guessesLeft -= 1;
    if (game.clue.guessesLeft <= 0) endGuessing(game);
  }
  return { result: result };
}

function endGuessing(game) {
  game.status = 'clue_needed';
  game.giver = game.giver === 'a' ? 'b' : 'a';
}
// ── clue-rules-end ──

interface Cell {
  word: string;
  kind: 'target' | 'neutral' | 'trap';
  revealed: boolean;
}

interface Game {
  version: number;
  status: 'new' | 'clue_needed' | 'guessing' | 'won' | 'lost';
  giver: 'a' | 'b';
  words: Cell[];
  clue: { word: string; count: number; guessesLeft: number; giver: 'a' | 'b' } | null;
  round: number;
  history: Array<{ round: number; clue: string; count: number; found: string[] }>;
  stats: { played: number; won: number; lost: number };
}

const GAME_FILE = 'game.json';

async function load(): Promise<Game> {
  let parsed: Partial<Game> = {};
  try {
    parsed = JSON.parse(await gezel.fs.read(GAME_FILE)) as Partial<Game>;
  } catch {
    // A missing game is a new one.
  }
  return {
    version: 1,
    status: parsed.status ?? 'new',
    giver: parsed.giver === 'b' ? 'b' : 'a',
    words: Array.isArray(parsed.words) ? parsed.words : [],
    clue: parsed.clue ?? null,
    round: parsed.round ?? 0,
    history: Array.isArray(parsed.history) ? parsed.history : [],
    stats: parsed.stats ?? { played: 0, won: 0, lost: 0 },
  };
}

async function save(game: Game): Promise<void> {
  await gezel.fs.write(GAME_FILE, `${JSON.stringify(game, null, 2)}\n`);
}

const game = await load();
let result = '';
let display = '';
let changed = false;

switch (input.action) {
  case 'new_game': {
    let bank: string[] = [];
    try {
      bank = (JSON.parse(await gezel.fs.read('words.json')) as { words?: string[] }).words ?? [];
    } catch {
      bank = [];
    }
    if (bank.length < BOARD_SIZE) throw new Error('words.json needs at least 16 words.');
    game.words = deal(bank, Math.random);
    game.status = 'clue_needed';
    game.giver = game.stats.played % 2 === 0 ? 'a' : 'b';
    game.clue = null;
    game.round = 0;
    game.history = [];
    changed = true;
    break;
  }
  case 'give_clue': {
    if (game.status !== 'clue_needed')
      throw new Error(
        game.status === 'guessing'
          ? 'The player is still guessing; no clue is needed yet.'
          : 'The game is over. Offer a new game instead of a clue.',
      );
    const count = Number(input.count);
    const problem = clueProblem(game.words, input.clue, count);
    if (problem) throw new Error(`${problem} Give another clue.`);
    const word = String(input.clue).trim().toUpperCase();
    game.clue = { word, count, guessesLeft: count + 1, giver: game.giver };
    game.status = 'guessing';
    game.round += 1;
    game.history = [...game.history, { round: game.round, clue: word, count, found: [] }];
    const say = String(input.say ?? '').replace(/\s+/g, ' ').trim().slice(0, 160);
    display = `Clue: ${word}, ${count}.${say ? ` ${say}` : ''}`;
    changed = true;
    break;
  }
  case 'guess': {
    if (game.status !== 'guessing') throw new Error('Wait for a clue before guessing.');
    const outcome = applyGuess(game, input.word);
    if (outcome.error) throw new Error(outcome.error);
    result = outcome.result;
    if (result === 'target') game.history[game.history.length - 1]?.found.push(String(input.word));
    if (game.status === 'won' || game.status === 'lost') {
      game.stats.played += 1;
      if (game.status === 'won') game.stats.won += 1;
      else game.stats.lost += 1;
    }
    changed = true;
    break;
  }
  case 'pass': {
    if (game.status !== 'guessing') throw new Error('There is no guessing turn to end.');
    endGuessing(game);
    changed = true;
    break;
  }
  case 'board':
    break;
  default:
    throw new Error(`Unknown action '${input.action}'.`);
}

if (changed) await save(game);

const over = game.status === 'won' || game.status === 'lost';
gezel.output({
  status: game.status,
  giver: game.giver,
  result,
  display,
  modelState: {
    status: game.status,
    yourWords: remaining(game.words, 'target'),
    trap: game.words.find((w) => w.kind === 'trap')?.word ?? '',
    otherWords: remaining(game.words, 'neutral'),
    found: game.words.filter((w) => w.kind === 'target' && w.revealed).map((w) => w.word),
    round: game.round,
    ...(game.clue && game.status === 'guessing' ? { currentClue: `${game.clue.word} ${game.clue.count}` } : {}),
  },
  summary: over
    ? `The player ${game.status === 'won' ? 'found all six words' : 'hit the trap'} in ${game.round} round(s). Games: ${game.stats.won} won, ${game.stats.lost} lost.`
    : `Round ${game.round}: ${remaining(game.words, 'target').length} of 6 words still to find.`,
});
